static java.util.List<Integer> topo(java.util.List<java.util.List<Integer>> g){
    int n=g.size();int[] deg=new int[n];
    for(var edges:g)for(int v:edges)deg[v]++;
    var q=new java.util.ArrayDeque<Integer>();
    var out=new java.util.ArrayList<Integer>();
    for(int i=0;i<n;i++)if(deg[i]==0)q.add(i);
    while(!q.isEmpty()){int u=q.remove();out.add(u);
        for(int v:g.get(u))if(--deg[v]==0)q.add(v);}
    if(out.size()!=n)throw new IllegalArgumentException("cycle");
    return out;
}
